var sortSentence = function(s) {
    const words = s.split(' ');
    const res = Array(words.length);
    for (const w of words) {
        const pos = Number(w[w.length - 1]) - 1;
        res[pos] = w.slice(0, -1);
    }
    return res.join(' ');
};
